// La foto descargada llega como dato binario (propiedad 'data').
// Anthropic necesita la imagen en base64 dentro del JSON del mensaje, así
// que la convertimos aquí. Si tu versión de n8n da un error en la línea de
// abajo, prueba con: items[0].binary.data.data (algunas versiones ya
// exponen el base64 directo ahí en vez de necesitar el helper).
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');

return [{
  json: {
    ...$('Configuración').item.json,
    image_base64: base64,
    image_media_type: items[0].binary.data.mimeType || 'image/jpeg'
  },
  binary: items[0].binary
}];

