// La respuesta de Anthropic trae el texto del modelo en content[0].text.
// Se pidió JSON puro en el prompt, pero por las dudas se limpian posibles
// bloques ```json ... ``` antes de parsear. Si el parseo falla (el modelo
// no devolvió JSON válido), se sigue igual: el borrador queda creado en el
// ERP con los campos extraídos vacíos, para revisar/completar a mano — la
// foto y el mensaje original NUNCA se pierden.
const prev = $('Convertir a base64').item.json;
const aiResponse = items[0].json;
let extracted = {};
let rawText = '';
try {
  rawText = aiResponse.content[0].text;
  const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch (err) {
  extracted = {};
}

return [{
  json: {
    ...prev,
    provider_ruc: extracted.provider_ruc || '',
    provider_name: extracted.provider_name || '',
    amount: extracted.amount != null ? String(extracted.amount) : '',
    currency: extracted.currency || '',
    document_number: extracted.document_number || '',
    document_date: extracted.document_date || '',
    raw_extraction: rawText || JSON.stringify(aiResponse)
  },
  binary: prev.binary || items[0].binary
}];

